#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    int M = 3;
    vector<int> A(M), B(M);
    for (int i = 0; i < M; i++) cin >> A[i];
    for (int i = 0; i < M; i++) cin >> B[i];

    int initial_sum = 0;
    for (int i = 0; i < M; i++) {
        initial_sum += min(A[i], B[(i + 1) % M]);
    }

    int size = 2 * M + 2;
    int s = 2 * M;
    int t = 2 * M + 1;

    vector<vector<array<int,3>>> adj(size);
    auto add_edge = [&](int u, int v, int cap) {
        adj[u].push_back({v, cap, (int)adj[v].size()});
        adj[v].push_back({u, 0, (int)adj[u].size() - 1});
    };

    for (int i = 0; i < M; i++) {
        add_edge(s, i, N);
        add_edge(M + i, t, B[i]);
        add_edge(i, M + i, A[i]);
        add_edge(i, M + (i - 1 + M) % M, A[i]);
    }

    vector<int> level(size), iter(size);

    auto bfs = [&](int s) {
        for (int i = 0; i < size; i++) level[i] = -1;
        level[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e : adj[v]) {
                int to = e[0], cap = e[1], rev = e[2];
                if (cap > 0 && level[to] < 0) {
                    level[to] = level[v] + 1;
                    q.push(to);
                }
            }
        }
    };

    function<int(int, int, int)> dfs = [&](int v, int t, int f) {
        if (v == t) return f;
        for (int &i = iter[v]; i < (int)adj[v].size(); i++) {
            auto &e = adj[v][i];
            int to = e[0], cap = e[1], rev = e[2];
            if (cap > 0 && level[v] < level[to]) {
                int d = dfs(to, t, min(f, cap));
                if (d > 0) {
                    e[1] -= d;
                    adj[to][rev][1] += d;
                    return d;
                }
            }
        }
        return 0;
    };

    int flow = 0;
    while (true) {
        bfs(s);
        if (level[t] < 0) break;
        for (int i = 0; i < size; i++) iter[i] = 0;
        while (true) {
            int f = dfs(s, t, INT_MAX);
            if (f == 0) break;
            flow += f;
        }
    }

    int result = N - flow;
    cout << result << " " << initial_sum << "\n";

    return 0;
}
